-- 3. Profiles
INSERT INTO profiles (user_id, display_name, bio, avatar_url) VALUES
  (1, 'Layla Nabulsi', 'Layla grew up in Jabal al-Weibdeh, Amman, where limestone walls and hanging jasmine shaped her visual language. Her practice explores the tension between tradition and contemporary Arab identity through large-format oil painting. She has exhibited across Amman, Beirut, and Berlin.', 'https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?w=200&q=80'),
  (2, 'Omar Khalil', 'Omar''s geometric abstractions draw directly from the tilework of the Umayyad Mosque and the ornamental patterns he studied as a child in his family''s tile workshop in downtown Amman. He works in acrylic and digital print, layering Islamic geometry with modernist minimalism.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&q=80'),
  (3, 'Sana al-Masri', 'Sana al-Masri is a Palestinian-Jordanian photographer whose lens turns to the everyday poetry of Amman''s streets — the chai vendors on Rainbow Street, the Roman Theatre at dusk, the balconies draped in laundry. Her images are quiet declarations of presence.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&q=80'),
  (4, 'Tariq Hamdan', 'Tariq studied at the Faculty of Fine Arts at the University of Jordan and spent three years in residence at studios in Florence and Cairo. His oil-on-canvas work merges classical European technique with Arab subject matter, reimagining the Grand Tour through a Levantine eye.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&q=80'),
  (5, 'Reem Aziz', 'Reem''s practice is rooted in Arabic calligraphy and its transformation into abstract mark-making. She writes to paint — her strokes begin as letters from Rumi or Mahmoud Darwish that dissolve into pure form. Each work is a meditation on language, silence, and the body.', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?w=200&q=80'),
  (6, 'Khalid Barakat', 'Khalid Barakat makes sculpture and mixed-media installations that respond to Jordan''s archaeological landscape — Petra, Jerash, the copper mines of Wadi Faynan. He uses earth, found clay, and bronze casting alongside digital fabrication in his Amman studio.', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=200&q=80'),
  (7, 'Dina Sabbagh', 'Dina is a textile artist and painter who learned to weave from her grandmother in Salt, Jordan. Her canvases are hybrid objects — painted, stitched, and unravelled — exploring the gendered labour of making in the Arab world and the intimacy woven into domestic craft.', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&q=80'),
  (8, 'Yusuf Nassar', 'Yusuf Nassar''s digital works interrogate how the Arab city is built and demolished — mapping Amman''s informal neighbourhoods, contested spaces, and the architecture of displacement through data-driven generative art. He collaborates with urban planners, architects, and musicians.', 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=200&q=80'),
  (9, 'Nour Jamal', 'Nour is a painter and printmaker whose work centres on the flora and fauna of Jordan — the black irises of the highlands, the bougainvillea tumbling down Aqaba walls, the starlings over Wadi Rum. Her palette borrows from the natural pigments of the earth beneath her feet.', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=200&q=80'),
  (10, 'Ibrahim Qasim', 'Ibrahim Qasim works at the intersection of conceptual art and Sufi philosophy. His installations — often using light, mirror, and sound — invite the viewer into states of contemplation and dissolution. He has shown at Darat al-Funun, the Jordan National Gallery, and Art Dubai.', 'https://images.unsplash.com/photo-1488161628813-04466f872be2?w=200&q=80');

