  (1, 'Amber at Dusk', 'A meditative exploration of negative space and the light that pools in the crevices of old stone.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg/1000px-Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg', 'Layla Nabulsi', '2022', 'Oil on canvas', '120 × 90 cm', -1.8, 1.5, -4.4, 0, 1.0, false),
